// Name is a short lower_snake_case identifier describing what is being observed.
//
// It is emitted as the "name" label for alerting rules; downstream integrations
// (including Opsgenie routing) consume that label, so it must be stable and safe
// for use as an identifier.
//
// It must be unique relative to the service name.
//
// Good examples:
//
// 	github_rate_limit_remaining
// 	search_error_rate
//
// Bad examples:
//
// 	repo_updater_github_rate_limit
// 	search_error_rate_over_5m
//
Name string

func isValidObservableIdentifier(identifier string) bool {
	if identifier == "" {
		return false
	}
	for _, r := range identifier {
		if r == '_' || (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			continue
		}
		return false
	}
	return true
}

if !isValidObservableIdentifier(o.Name) {
	return errors.Errorf("Name must be a lower_snake_case identifier; found %q", o.Name)
}

